arguments.command:
export DRIVE_SESSION_TAG="nothingness_linux_debug"; export DRIVE_TARGET=linux; export DRIVE_RUN_LOG="/tmp/flutter_run_${DRIVE_SESSION_TAG}.log"; export DRIVE_FLUTTER_FIFO="/tmp/flutter_input_${DRIVE_SESSION_TAG}";
CFG='{"type":"dot","name":"Dot","minDotSize":20.0,"maxDotSize":120.0,"dotOpacity":1.0,"textOpacity":1.0,"sensitivity":1.5,"showSongInfo":true,"textScale":1.0}';
./.agents/skills/agent-emulator-debugging/scripts/drive.py pref screen_config_dot=${CFG}:string
./.agents/skills/agent-emulator-debugging/scripts/drive.py pref active_screen_id=dot:string
./.agents/skills/agent-emulator-debugging/scripts/drive.py restart --delay 3
sleep 1
FILE="/tmp/nothingness_shots/An Ultra Mega Long Artist Name That Should Wrap Or Ellipsize - An Extremely Long Song Title That Should Also Wrap Or Ellipsize.mp3";
./.agents/skills/agent-emulator-debugging/scripts/drive.py play "$FILE"
./.agents/skills/agent-emulator-debugging/scripts/drive.py shoot dot_text_normal_fixed --pixel-ratio 2

